-- ۱.۲۷.۸۸ — ممیزی روان‌سنجی (quick wins): شناسنامهٔ ابزار — پر کردن tool_source/tool_norm برای ۱۹ قالب ce-* باتریِ مقیم DB
-- مقادیر عیناً از فیلد «source» بلوک‌های JSON باتری برداشت شده‌اند (بدون بازنویسی یا بهبود ادعا):
--   tool_source = متن کامل فیلد source همان بلوک (verbatim)؛
--   tool_norm   = وضعیت باند/هنجار بر پایهٔ همان متن (مستند / کالیبراسیون داخلی / بدون مبدأ — نیازمند تأیید)؛
--   فرم‌های بدون باند و هنجار (شرح‌حال v2/v3) عمداً NULL می‌مانند. دو چیپ کد-مقیم ce-sensory-chip-v1 و
--   ce-read-core-v1 ردیف case_event_types ندارند (SENSORY_CHIP_KEY/READ_CORE_KEY در pure.ts) و قالب‌های
--   خارج از باتری ادعای منبعی در JSON ندارند — همه NULL می‌مانند. رجیستری کامل: docs/INSTRUMENT-SOURCES.md
-- این UPDATEها Idempotent هستند (مقدار ثابت می‌نویسند) و فقط-افزودنی‌اند؛ ستون‌ها در 0117_tool_metadata.sql ساخته شده‌اند.

UPDATE case_event_types SET tool_source = 'Goodman 1997 — بازآفرینی فارسی (کالیبراسیون m86؛ لنگر پاسخ توصیفی مطابق مرجع). باندهای کل ملاک چهارباندی نسخهٔ معلم برگهٔ رسمی ۴–۱۷ سال (sdqinfo): ۰–۱۱ نزدیک به میانگین / ۱۲–۱۵ کمی بالا / ۱۶–۱۸ بالا / ۱۹–۴۰ خیلی بالا (m176 — پیش از این سه‌باندی بود). باندهای زیرمقیاس کالیبراسیون داخلی — بازتأیید با دادهٔ مرکز.', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-sdq-t-v1';
UPDATE case_event_types SET tool_source = 'Swanson SNAP-IV-26 (رایگان) — لنگرهای رسمی شدت (اصلاً/کمی/خیلی/خیلی زیاد). برش‌ها صدک ۹۵ والد (Swanson 2001/Bussing 2008): کم‌توجهی ۱٫۷۸، تکانشگری ۱٫۴۴، نافرمانی ۱٫۸۸ — m176: نافرمانی از ۱٫۴۷ نادرستِ m86 به مقدار منبع ۱٫۸۸ اصلاح شد (۱٫۶۷ برش «ترکیبی» والد است نه نافرمانی). باندهای نمایشی = برش × تعداد گویه + باند مرزی داخلی.', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-snap-iv-p-v1';
UPDATE case_event_types SET tool_source = 'Swanson SNAP-IV-26 — لنگرهای رسمی شدت. برش‌ها صدک ۹۵ معلم (Swanson 2001): کم‌توجهی ۲٫۵۶، تکانشگری ۱٫۷۸ (m176: مستندسازی از ۱٫۸۰ به مقدار منبع — مرز نمایشی ۱۶ بدون تغییر)، نافرمانی ۱٫۳۸.', tool_norm = 'مستند', updated_at = datetime('now') WHERE key = 'ce-snap-iv-t-v1';
UPDATE case_event_types SET tool_source = 'Birmaher 1999 (رایگان) — لنگرهای رسمی درستی. برش کل ≥۲۵ (برگهٔ رسمی) — بازتأیید با دادهٔ مرکز در برنامه. برش زیرمقیاس‌ها مطابق برگهٔ رسمی (AACAP/OHSU): جسمانی ۷+، فراگیر ۹+، جدایی ۵+، اجتماعی ۸+ (m176: از ۶ اصلاح شد — روی چیدمان ۸ گویه‌ای فعلی تقریبی است)، مدرسه ۳ (m176: از ۱ به ۳ اصلاح شد). چیدمان گویه‌ها بازآفرینی است (۱۱/۹/۱۰/۸/۳ در برابر رسمی ۱۳/۹/۸/۷/۴) — هم‌ترازسازی با نسخهٔ رسمی در دستور کار بازبینی.', tool_norm = 'مستند', updated_at = datetime('now') WHERE key = 'ce-scared-p-v1';
UPDATE case_event_types SET tool_source = 'Goodman 1997 — نسخهٔ والد؛ ساخت آیتم‌ها (کلید و ترتیب) و لنگرهای پاسخ عین نسخهٔ معلم (ce-sdq-t-v1)؛ فقط متنِ پنج آیتمِ متکی به کلاس، والدپسند بازنویسی شده است. m176: باندهای کل از هم‌سانِ معلم (تصمیم T5/m150) به برش رسمی نسخهٔ والد برگهٔ ۴–۱۷ (۰–۱۳ / ۱۴–۱۶ / ۱۷–۱۹ / ۲۰–۴۰) تغییر کرد — مقایسهٔ والد×معلم پس از نمره‌دهی هر گزارش‌دهنده با برش خودش انجام می‌شود.', tool_norm = 'مستند', updated_at = datetime('now') WHERE key = 'ce-sdq-p-v1';
UPDATE case_event_types SET tool_source = 'شرح‌حال نظام‌مند کودک (هفت بخش) + فیلدهای ساخت‌یافتهٔ تفریق تشخیصی موتور (تغییر مدرسه/غیبت/بحران، مشکل حسی، زبان خانواده، مداخلهٔ قبلی) — m86 بازطراحی روایی با سربرگ بخش؛ کلیدهای مصرفی infer.ts دست‌نخورده ماندند', updated_at = datetime('now') WHERE key = 'ce-anamnesis-v2';
UPDATE case_event_types SET tool_source = 'نسخهٔ ۳ شرح‌حال — m148 موج ۲: هفت بخش نسخهٔ ۲ حفظ شد و فیلدهای تفریق تشخیصی ساخت‌یافته با کلیدهای ثابت snake_case آمدند (sld_read/write/calc_concern، attention_concern، hyper_concern، decline_scope، morning_somatic، exam_anxiety، crisis_event، sensory_concern، home_language، school_change، absence_level، prev_intervention) — منبع سیگنال‌های شرح‌حال موتور. نسخهٔ ۲ فقط برای پرونده‌های قدیمی است و برای ورودی جدید غیرفعال شده.', updated_at = datetime('now') WHERE key = 'ce-anamnesis-v3';
UPDATE case_event_types SET tool_source = 'CBM خواندن: واژهٔ درست در دقیقه (هنجار پنجاهم صدک در instruments.ts) + خطا + کدگشایی واژهٔ بی‌معنی (۲۰ مورد)', tool_norm = 'بدون مبدأ — نیازمند تأیید', updated_at = datetime('now') WHERE key = 'ce-probe-read-v1';
UPDATE case_event_types SET tool_source = 'دیکتهٔ خطادار به تفکیک نوع (آوایی/تصویری/قاعده‌ای) + روانی نوشتن حروف در ۱۵ ثانیه (هنجار در instruments.ts)', tool_norm = 'بدون مبدأ — نیازمند تأیید', updated_at = datetime('now') WHERE key = 'ce-probe-write-v1';
UPDATE case_event_types SET tool_source = 'CBM حساب: ارقام درست در ۲ دقیقه + مقایسهٔ مقدار (۱۰ جفت) + خطای برآورد خط عددی (٪) — هنجار در instruments.ts', tool_norm = 'بدون مبدأ — نیازمند تأیید', updated_at = datetime('now') WHERE key = 'ce-probe-calc-v1';
UPDATE case_event_types SET tool_source = 'Wilson DCDQ''07 (رایگان با ارجاع) — لنگرهای رسمی شباهت‌سنجی پنج‌درجه‌ای. نسخهٔ خام ۱۵..۷۵ → سامانه ۰..۶۰. برش‌های رسمی سنی دوباندی: ۵–۷ سال = ۴۶ (→۳۱)، ۸–۹ سال = ۵۵ (→۴۰)، ۱۰–۱۵ سال = ۵۷ (→۴۲). m176: باند مرزی همه‌سنی ۳۱–۴۱ (بدون پشتوانهٔ منبع) حذف و به باند محتاطانهٔ «بسته به سن» ۳۲–۴۲ تبدیل شد — منبع باند مرزی ندارد و زیر برشِ هر گروه سنی = نشانهٔ DCD. حداکثر زیرمقیاس‌ها: کنترل ۳۰ / ظریف ۲۵ / عمومی ۲۰ — با ۶/۵/۴ گویه هم‌خوان است.', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-dcdq-v1';
UPDATE case_event_types SET tool_source = 'ملاک‌های اختلال یادگیری خاص — خواندن (F81.0) بازآفرینی فارسی؛ هر آیتم به ملاک حرف‌دار در rules.ts گره خورده؛ لنگر شدت سه‌درجه‌ای m86', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-sld-read-v1';
UPDATE case_event_types SET tool_source = 'ملاک‌های اختلال یادگیری خاص — بیان نوشتاری (F81.81) بازآفرینی فارسی؛ گره ملاک‌ها در rules.ts؛ لنگر شدت سه‌درجه‌ای m86', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-sld-wri-v1';
UPDATE case_event_types SET tool_source = 'ملاک‌های اختلال یادگیری خاص — ریاضی (F81.2) بازآفرینی فارسی؛ گره ملاک‌ها در rules.ts؛ لنگر شدت سه‌درجه‌ای m86', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-sld-calc-v1';
UPDATE case_event_types SET tool_source = 'ملاک‌های ASD (F84.0): A هر سه، B حداقل دو از چهار — بازآفرینی فارسی؛ قاعدهٔ ملاکی در rules.ts؛ ارجاع تخصصی همیشه خط قرمز است؛ لنگر شدت سه‌درجه‌ای m86', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-asd-criteria-v1';
UPDATE case_event_types SET tool_source = 'اختلال زبان (F80.2) / اختلال اصوات گفتار (F80.0) / روانی گفتار (F80.81) — بازآفرینی فارسی؛ آیتم بحرانی کم‌شنوایی = ارجاع؛ لنگر شدت سه‌درجه‌ای m86', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-speech-criteria-v1';
UPDATE case_event_types SET tool_source = 'ملاک‌های ODD (F91.3): حداقل ۴ ملاک A با نمرهٔ ۲ + طول ≥۶ ماه — قاعده در rules.ts؛ تفکیک از ADHD تکانشی الزامی؛ لنگر شدت سه‌درجه‌ای m86', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-odd-criteria-v1';
UPDATE case_event_types SET tool_source = 'سنجهٔ انطباقی ۱۲ آیتمی — بازآفرینی مرکز بر پایهٔ حوزه‌های انطباق (ارتباط/مراقبت از خود/اجتماعی/کار مدرسه)؛ هر آیتم ۰–۲، نمرهٔ بالاتر = انطباق بهتر. برش‌های سه‌گانهٔ پایین/مرزی/نرمال اولیه است (پایین ≤۱۲، مرزی ۱۳–۱۷، نرمال ۱۸–۲۴) — کالیبراسیون با دادهٔ مرکز در. ملاک تفکیک ID از دیرآموز (طرح §۳.۱): FSIQ≤۷۰ همراه انطباق پایین → مسیر ID.', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-id-adapt-v1';
UPDATE case_event_types SET tool_source = 'ملاک‌های کلاسی دشواری یادگیری خاص — بازآفرینی مرکز برای مشاهدهٔ معلم (T7/m150-b — طرح واحد §۲ P0 ردیف ۴): روانی خواندن/املاء و نگارش/حساب ذهنی و مسئله. زیرمقیاس‌ها sld_read/sld_write/sld_calc — هم‌نام کلیدهای سیگنال شرح‌حال v3 (ANAMNESIS_V3_SIGNAL_SPEC: anam.sld_read/sld_write/sld_calc) تا موتور هر دو منبع را بی‌بازنویسی بخواند. هر آیتم ۰–۲ (فراوانی مشاهده)، نمرهٔ بالاتر = نشانهٔ بیشتر. برش‌های سه‌گانهٔ عادی/مرزی/قابل توجه اولیه است — کالیبراسیون با دادهٔ مرکز در.', tool_norm = 'کالیبراسیون داخلی', updated_at = datetime('now') WHERE key = 'ce-sld-class-t-v1';
